// Arma la notificación de la historia 1 (spec-n8n.md 2.4)
const TIPOS = {
  PLAGA: { titulo: 'Plaga registrada', prioridad: 'high' },
  ENFERMEDAD: { titulo: 'Enfermedad registrada', prioridad: 'high' },
  DANIO: { titulo: 'Daño registrado', prioridad: 'normal' },
  OTRO: { titulo: 'Otra incidencia registrada', prioridad: 'normal' },
};
return $input.all().map(({ json: sobre }) => {
  const d = sobre.datos || {};
  const tipo = TIPOS[d.tipo];
  if (!tipo) throw new Error(`Evento sin datos.tipo válido: ${JSON.stringify(sobre)}`);
  const descripcion = String(d.descripcion || '').slice(0, 100);
  return {
    json: {
      idCorrelacion: sobre.idCorrelacion,
      mensaje: {
        topic: 'tecnicos',
        notification: { title: tipo.titulo, body: `${d.registradaPor?.nombre ?? 'Alguien'}: ${descripcion}` },
        data: {
          tipo: 'INCIDENCIA_REGISTRADA',
          idIncidencia: String(d.idIncidencia),
          tipoIncidencia: String(d.tipo),
          idParcela: String(d.idParcela),
        },
        android: { priority: tipo.prioridad },
      },
    },
  };
});
